using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using DragonCompanion;
class MotionAudit{
 static bool Different(byte[] a,byte[] b,int i){return a[i]!=b[i]||a[i+1]!=b[i+1]||a[i+2]!=b[i+2]||a[i+3]!=b[i+3];}
 [STAThread]static void Main(string[] args){string root=Path.GetFullPath(args[0]);string output=Path.Combine(root,"out","renders");Directory.CreateDirectory(output);var report=new System.Collections.Generic.List<object>();foreach(string form in new[]{"chibi","medium","full","xhigh","max","ultra"}){var p=new AnimatedPortrait();var b=new BitmapImage(new Uri(Path.Combine(root,"assets",form+".png")));p.Form=form;p.Source=b;p.MotionEnabled=false;typeof(AnimatedPortrait).GetField("switchedAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(p,-100.0);p.Measure(new Size(300,400));p.Arrange(new Rect(0,0,300,400));p.UpdateLayout();byte[][] bytes=new byte[3][];double[] times={0,1.7,3.34};for(int i=0;i<3;i++){p.Step(times[i]);p.UpdateLayout();var r=new RenderTargetBitmap(300,400,96,96,PixelFormats.Pbgra32);r.Render(p);bytes[i]=new byte[300*400*4];r.CopyPixels(bytes[i],300*4,0);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(r));using(var f=File.Create(Path.Combine(output,form+"-motion-"+i+".png")))encoder.Save(f);}
 int changed=0,blinkChanged=0,visible=0;for(int i=0;i<bytes[0].Length;i+=4){if(bytes[0][i+3]>128)visible++;if(Different(bytes[0],bytes[1],i))changed++;if(Different(bytes[0],bytes[2],i))blinkChanged++;}if(visible<10000||changed<300||blinkChanged<300)throw new Exception("Motion rendering failed: "+form);report.Add(new{form=form,visiblePixels=visible,changedPixels=changed,changedAtBlink=blinkChanged});}File.WriteAllText(Path.Combine(output,"motion-audit.json"),Json.Encode(new{passed=true,frames=report,renderer="WPF textured mesh and vector effects",utc=DateTime.UtcNow.ToString("O")}));Console.WriteLine("PASS animated pixels across six forms");}
}
